Method.Implementation:
	set tSC = $$$OK

 set statement=##class(%SQL.Statement).%New()
 set status=statement.%Prepare("Select ID,Username, Password,BusinessPartner from Ens_Config.Credentials where ID = '" _ ..CredentialName _"'")
 if $$$ISERR(status) { do $system.OBJ.DisplayError(status) }
 set resultset=statement.%Execute()
 while resultset.%Next() {
    $$$LOGINFO( resultset.%Get("ID"))
    set pUser = resultset.%Get("Username")
    set pPassword = resultset.%Get("Password")
 }
 $$$LOGINFO( pUser )
 if (pUser = "")
 {
	 QUIT $$$ERROR("Could not get username from the Credential")
 }

 set credentialsObj=##class(Ens.Config.Credentials).%New()


 Set tSession=##class(%Net.SSH.Session).%New()


	set stat = tSession.Connect(..RemoteServer) 
	if $$$ISERR(stat) { $$$LOGERROR( "Not connected " _ stat) Quit stat}

    Set stat = tSession.AuthenticateWithUsername(pUser,pPassword)

	Set tSC=tSession.OpenSFTP(.sftp)
	If 'tSC {
		$$$LOGERROR("Failed to Authenticate to SFTP remoteServer"_pHost_" with user: "_pUser)

		Quit tSC
	}
	Set tSC=sftp.Dir(..RemoteDirectory,.tTempListing,..SearchPattern)
	Set i=$O(tTempListing("")) 
	While i'="" {
		set DataFile = $LG(tTempListing(i),1)
		$$$LOGINFO("Get: " _ DataFile _ " from " _ ..RemoteDirectory)
		Set tSC=sftp.Get(..RemoteDirectory _ DataFile, ..TargetDirectory _ DataFile,)
		$$$LOGINFO( "sftp.Get: " _ tSC)

			If ($$$ISOK(tSC))	
			{
				Set tSC = sftp.Delete(..RemoteDirectory _ DataFile)
				$$$LOGINFO( "sftp.Delete: " _ tSC)

				Try {
					if (##class(%File).Exists(..TargetDirectory _ DataFile))
					{
						 set fSz = ##class(%File).GetFileSize(..TargetDirectory _ DataFile)
						 $$$LOGINFO( DataFile _ ", size: " _ fSz )
						 if (fSz > 0 )
						 {
							 #dim tRequestObj As EnsLib.HL7.Message

							 Set tRequestObj = ##class(EnsLib.HL7.Message).ImportFromFile(..TargetDirectory _ DataFile)

							 set tSC = tRequestObj.DocTypeSet(..DocType)
							 $$$LOGINFO( "Create Hl7 message: size: " _ tRequestObj.FullSize _ ", stat: " _ tSC)

							 set tSC =  ##Class(EnsLib.Testing.Service).SendTestRequest(..TargetComp, tRequestObj, .tResponse, .tSessionId)

							 if ($$$ISOK(tSC))
							 {
								 $$$LOGINFO( "Call SendTestRequest to "_ ..TargetComp _ ", stat: " _ tSC _ ", tResponse " _ tResponse _ ", tSessionId " _ tSessionId)
								 Do ##class(%File).Delete(..TargetDirectory _ DataFile)
							 }
							 else
							 {
								 $$$LOGERROR("SendTestRequest error: " _ tSC)
							 }
						 }
					}						        	
				}
				Catch (ex) {
					Set tSC = ex.AsStatus()
				}
			}
			If $$$ISERR(tSC) {
				$$$LOGERROR( $system.Status.GetErrorText(tSC))

			}

		Set i=$O(tTempListing(i))
	}

	return tSC
